select ('b2000000-0000-4000-8000' || lpad((100 + (x->>'n')::int)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', x->>'t', x->>'p', x->'d', x->>'e', null,
       (x->>'m')::numeric, x->>'df', x->>'tp', x->>'st',
       array['MYP 2', 'Mathematics', 'formative', 'assess-prep'], 'published', x->'cfg', '3c3ed712-f409-4aa1-a645-816418e22ec4',
       'MYP', 'MYP 2 Mathematics', '0a400000-0000-4000-8000-000000000030', 'approved', 'manual', '0a400000-0000-4000-8000-000000000107'
  from jsonb_array_elements('[{"n":1,"t":"numeric","p":"A cyclist travels 120 km in 4 hours at a steady speed. What is her speed?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A cyclist travels 120 km in 4 hours at a steady speed. What is her speed?"}]}]},"e":"Speed = distance ÷ time = 120 ÷ 4 = 30 km/h.\n\nHint for next time: Always write the unit with a rate.","m":1,"df":"easy","tp":"rate","st":"unit rate","cfg":{"source":"assess-prep-myp2-formative","question_number":1,"myp_criterion":"A","next_time_hint":"Always write the unit with a rate.","assessment_style":"assess_prep_typed","hints":["Speed compares distance with time. Which operation links them?","Divide the distance travelled by the time taken."],"numeric_answer":30,"tolerance":0}},{"n":2,"t":"numeric","p":"A tap fills 36 litres of water in 6 minutes. How many litres does it fill in one minute?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A tap fills 36 litres of water in 6 minutes. How many litres does it fill in one minute?"}]}]},"e":"Rate = 36 ÷ 6 = 6 litres per minute.\n\nHint for next time: A unit rate tells you the amount for ONE minute.","m":1,"df":"easy","tp":"rate","st":"unit rate","cfg":{"source":"assess-prep-myp2-formative","question_number":2,"myp_criterion":"A","next_time_hint":"A unit rate tells you the amount for ONE minute.","assessment_style":"assess_prep_typed","hints":["A unit rate tells you the amount for ONE minute.","Divide the total litres by the number of minutes."],"numeric_answer":6,"tolerance":0}},{"n":3,"t":"numeric","p":"A car uses 21 litres of fuel to travel 315 km. How many litres does it use per 100 km? Give your answer to 2 decimal places.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A car uses 21 litres of fuel to travel 315 km. How many litres does it use per 100 km? Give your answer to 2 decimal places."}]}]},"e":"Litres per km = 21 ÷ 315 = 0.0666… So per 100 km: 0.0666… × 100 = 6.67 litres (2 d.p.).\n\nHint for next time: Find the rate for 1 first, then scale.","m":2,"df":"medium","tp":"rate","st":"fuel consumption","cfg":{"source":"assess-prep-myp2-formative","question_number":3,"myp_criterion":"D","next_time_hint":"Find the rate for 1 first, then scale.","assessment_style":"assess_prep_typed","hints":["First find the fuel used for ONE kilometre.","Divide 21 by 315, then scale your answer up to 100 km."],"numeric_answer":6.67,"tolerance":0.01}},{"n":4,"t":"assess_parts","p":"Tap A fills a 240 litre tank in 8 minutes. Tap B fills the same tank in 12 minutes.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tap A fills a 240 litre tank in 8 minutes. Tap B fills the same tank in 12 minutes."}]}]},"e":"Tap A: 240 ÷ 8 = 30 L/min. Tap B: 240 ÷ 12 = 20 L/min. Tap A is faster because its rate in litres per minute is greater.\n\nHint for next time: Rate = amount ÷ time for the same tank.","m":3,"df":"medium","tp":"rate","st":"comparing rates","cfg":{"source":"assess-prep-myp2-formative","question_number":4,"myp_criterion":"D","next_time_hint":"Rate = amount ÷ time for the same tank.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What is the filling rate of tap A?","kind":"numeric","points":1,"hints":["Rate = amount ÷ time for the same tank.","Divide 240 litres by tap A''s time."],"answer":30,"tolerance":0,"unit":"L/min"},{"id":"b","label":"(b)","prompt":"What is the filling rate of tap B?","kind":"numeric","points":1,"hints":["Use the same tank size with tap B''s time.","Divide 240 litres by tap B''s time."],"answer":20,"tolerance":0,"unit":"L/min"},{"id":"c","label":"(c)","prompt":"Which tap is faster? Type: Tap A or Tap B.","kind":"text","points":1,"hints":["Compare the two rates: a greater litres-per-minute fills sooner.","Compare your answers to (a) and (b)."],"accepted":["Tap A","A"]}]}},{"n":5,"t":"short_answer","p":"Write the ratio 12 : 18 in its simplest form. Type it like 2:3.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write the ratio 12 : 18 in its simplest form. Type it like 2:3."}]}]},"e":"Both numbers divide by 6: 12 : 18 = 2 : 3.\n\nHint for next time: Look for a number that divides both 12 and 18.","m":1,"df":"easy","tp":"ratio","st":"simplifying ratios","cfg":{"source":"assess-prep-myp2-formative","question_number":5,"myp_criterion":"A","next_time_hint":"Look for a number that divides both 12 and 18.","assessment_style":"assess_prep_typed","hints":["Look for a number that divides both 12 and 18.","Divide both sides by their highest common factor."],"accepted":["2:3","2/3","2 : 3"]}},{"n":6,"t":"assess_parts","p":"The tape diagram shows counters shared between red and blue in the ratio 3 : 2. There are 40 counters in total.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The tape diagram shows counters shared between red and blue in the ratio 3 : 2. There are 40 counters in total."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"tape","title":"Red : Blue counters (40 in total)","tapeRows":[{"label":"Red","segments":[{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1}]},{"label":"Blue","segments":[{"label":"?","span":1},{"label":"?","span":1}]}]}}}]},"e":"There are 5 equal parts, so one part = 40 ÷ 5 = 8 counters. Red has 3 parts: 3 × 8 = 24 counters.\n\nHint for next time: Start by finding the total number of parts in the ratio.","m":2,"df":"medium","tp":"ratio","st":"sharing with a tape diagram","cfg":{"source":"assess-prep-myp2-formative","question_number":6,"myp_criterion":"A","next_time_hint":"Start by finding the total number of parts in the ratio.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many counters is ONE part worth?","kind":"numeric","points":1,"hints":["Start by finding the total number of parts in the ratio.","Add the parts 3 and 2, then share 40 counters equally between them."],"answer":8,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many counters are red?","kind":"numeric","points":1,"hints":["Red takes 3 of the equal parts.","Multiply the value of one part by the number of red parts."],"answer":24,"tolerance":0}]}},{"n":7,"t":"assess_parts","p":"A paint colour mixes red and yellow paint in the ratio 2 : 5. A decorator needs 35 litres of the mixture.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A paint colour mixes red and yellow paint in the ratio 2 : 5. A decorator needs 35 litres of the mixture."}]}]},"e":"Total parts = 2 + 5 = 7, so one part = 35 ÷ 7 = 5 litres. Red: 2 × 5 = 10 litres. Yellow: 5 × 5 = 25 litres.\n\nHint for next time: Start by finding the total number of parts in the ratio.","m":2,"df":"medium","tp":"ratio","st":"sharing in a ratio","cfg":{"source":"assess-prep-myp2-formative","question_number":7,"myp_criterion":"D","next_time_hint":"Start by finding the total number of parts in the ratio.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many litres of red paint are needed?","kind":"numeric","points":1,"hints":["Start by finding the total number of parts in the ratio.","Share 35 litres into 7 equal parts, then take the red share."],"answer":10,"tolerance":0,"unit":"litres"},{"id":"b","label":"(b)","prompt":"How many litres of yellow paint are needed?","kind":"numeric","points":1,"hints":["Yellow takes 5 of the equal parts.","Multiply the value of one part by 5 — or subtract red from 35."],"answer":25,"tolerance":0,"unit":"litres"}]}},{"n":8,"t":"assess_parts","p":"$84 is shared between Amara and Bola in the ratio 3 : 4.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"$84 is shared between Amara and Bola in the ratio 3 : 4."}]}]},"e":"Total parts = 7, so one part = 84 ÷ 7 = $12. Amara: 3 × 12 = $36. Bola: 4 × 12 = $48. Check: 36 + 48 = 84.\n\nHint for next time: Start by finding the total number of parts in the ratio.","m":2,"df":"medium","tp":"ratio","st":"sharing money","cfg":{"source":"assess-prep-myp2-formative","question_number":8,"myp_criterion":"D","next_time_hint":"Start by finding the total number of parts in the ratio.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How much does Amara receive?","kind":"numeric","points":1,"hints":["Start by finding the total number of parts in the ratio.","Share $84 into 7 equal parts, then take Amara''s 3 parts."],"answer":36,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"How much does Bola receive?","kind":"numeric","points":1,"hints":["Bola takes 4 of the equal parts.","Multiply the value of one part by 4 — or subtract Amara''s share from $84."],"answer":48,"tolerance":0,"unit":"$"}]}},{"n":9,"t":"assess_parts","p":"Two ratios are linked: a : b = 2 : 3 and b : c = 4 : 5.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two ratios are linked: a : b = 2 : 3 and b : c = 4 : 5."}]}]},"e":"Make b the same in both ratios: multiply a : b by 4 → 8 : 12, and b : c by 3 → 12 : 15. So a : b : c = 8 : 12 : 15 (35 parts). For a total of 70, one part = 2, so c = 15 × 2 = 30.\n\nHint for next time: The shared letter b must be worth the same in both ratios.","m":2,"df":"hard","tp":"ratio","st":"combining ratios","cfg":{"source":"assess-prep-myp2-formative","question_number":9,"myp_criterion":"B","next_time_hint":"The shared letter b must be worth the same in both ratios.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write the combined ratio a : b : c in its simplest form. Type it like 8:12:15.","kind":"text","points":1,"hints":["The shared letter b must be worth the same in both ratios.","Scale each ratio so that b becomes the lowest common multiple of 3 and 4."],"accepted":["8:12:15","8 : 12 : 15"]},{"id":"b","label":"(b)","prompt":"The three quantities total 70. What is the value of c?","kind":"numeric","points":1,"hints":["Add the parts of your combined ratio to share 70.","Find one part from the total, then take c''s parts."],"answer":30,"tolerance":0}]}},{"n":10,"t":"assess_parts","p":"The double number line shows that 3 pens cost $6.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The double number line shows that 3 pens cost "},{"type":"text","text":"$6."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"double_number_line","title":"Cost of pens","lines":[{"label":"Pens","unit":"pens","max":7,"ticks":[{"at":0,"label":"0"},{"at":3,"label":"3"},{"at":7,"label":"7"}]},{"label":"Cost","unit":"$","max":14,"ticks":[{"at":0,"label":"0"},{"at":6,"label":"6"},{"at":14,"label":"?"}]}]}}}]},"e":"One pen costs 6 ÷ 3 = $2. Seven pens cost 7 × 2 = $14.\n\nHint for next time: The line links 3 pens with $6. Find the value for one first.","m":2,"df":"easy","tp":"proportion","st":"double number line","cfg":{"source":"assess-prep-myp2-formative","question_number":10,"myp_criterion":"A","next_time_hint":"The line links 3 pens with $6. Find the value for one first.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What does ONE pen cost?","kind":"numeric","points":1,"hints":["The line links 3 pens with $6. Find the value for one first.","Divide the cost of 3 pens by 3."],"answer":2,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"What do 7 pens cost?","kind":"numeric","points":1,"hints":["Use the cost of one pen and scale up.","Multiply the unit cost by 7."],"answer":14,"tolerance":0,"unit":"$"}]}},{"n":11,"t":"numeric","p":"A recipe for 4 people uses 300 g of flour. How much flour is needed for 1 person?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A recipe for 4 people uses 300 g of flour. How much flour is needed for 1 person?"}]}]},"e":"For 1 person: 300 ÷ 4 = 75 g.\n\nHint for next time: This is the unitary method: find the amount for ONE person first.","m":1,"df":"easy","tp":"proportion","st":"unitary method","cfg":{"source":"assess-prep-myp2-formative","question_number":11,"myp_criterion":"A","next_time_hint":"This is the unitary method: find the amount for ONE person first.","assessment_style":"assess_prep_typed","hints":["This is the unitary method: find the amount for ONE person first.","Divide 300 g by the 4 people."],"numeric_answer":75,"tolerance":0}},{"n":12,"t":"numeric","p":"On a map, 1 cm represents 5 km. Two towns are 7.5 cm apart on the map. What is the real distance between them?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On a map, 1 cm represents 5 km. Two towns are 7.5 cm apart on the map. What is the real distance between them?"}]}]},"e":"Real distance = 7.5 × 5 = 37.5 km.\n\nHint for next time: Multiply by the scale — check the unit changes from cm to km.","m":2,"df":"medium","tp":"proportion","st":"map scales","cfg":{"source":"assess-prep-myp2-formative","question_number":12,"myp_criterion":"D","next_time_hint":"Multiply by the scale — check the unit changes from cm to km.","assessment_style":"assess_prep_typed","hints":["Every centimetre on the map stands for 5 km in real life.","Multiply the map distance by the scale value."],"numeric_answer":37.5,"tolerance":0.05}},{"n":13,"t":"assess_parts","p":"Five identical bottles hold 7.5 litres of water in total.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Five identical bottles hold 7.5 litres of water in total."}]}]},"e":"One bottle holds 7.5 ÷ 5 = 1.5 litres. Eight bottles hold 8 × 1.5 = 12 litres.\n\nHint for next time: Find the amount for one first — the unitary method.","m":2,"df":"medium","tp":"proportion","st":"unitary method","cfg":{"source":"assess-prep-myp2-formative","question_number":13,"myp_criterion":"A","next_time_hint":"Find the amount for one first — the unitary method.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How much water does ONE bottle hold?","kind":"numeric","points":1,"hints":["Find the amount for one first — the unitary method.","Divide 7.5 litres by the 5 bottles."],"answer":1.5,"tolerance":0,"unit":"litres"},{"id":"b","label":"(b)","prompt":"How much water do 8 bottles hold?","kind":"numeric","points":1,"hints":["Scale the one-bottle amount up to 8 bottles.","Multiply your answer to (a) by 8."],"answer":12,"tolerance":0,"unit":"litres"}]}},{"n":14,"t":"assess_parts","p":"Spot the mistake. A student writes: \"4 shirts cost $48. 10 shirts is 6 more shirts, so 10 shirts cost 48 + 6 = $54.\"","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spot the mistake. A student writes: \"4 shirts cost "},{"type":"text","text":"$48. 10 shirts is 6 more shirts, so 10 shirts cost 48 + 6 = $"},{"type":"text","text":"54.\""}]}]},"e":"The mistake is adding instead of scaling: price grows in proportion, not by the number of extra shirts. One shirt costs 48 ÷ 4 = $12, so 10 shirts cost 10 × 12 = $120.\n\nHint for next time: Ignore the student''s method. Find the unit price from 4 shirts.","m":3,"df":"hard","tp":"proportion","st":"spot the mistake: proportional reasoning","cfg":{"source":"assess-prep-myp2-formative","question_number":14,"myp_criterion":"C","next_time_hint":"Ignore the student''s method. Find the unit price from 4 shirts.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What does ONE shirt actually cost?","kind":"numeric","points":1,"hints":["Ignore the student''s method. Find the unit price from 4 shirts.","Divide $48 by 4 shirts."],"answer":12,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"Type the correct cost of 10 shirts.","kind":"numeric","points":2,"hints":["Proportional quantities are scaled by multiplication, not addition.","Multiply the cost of one shirt by 10."],"answer":120,"tolerance":0,"unit":"$"}]}},{"n":15,"t":"assess_parts","p":"The Venn diagram shows students who play football (F) and basketball (B).","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Venn diagram shows students who play football (F) and basketball (B)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Sports played","venn":{"leftLabel":"F","rightLabel":"B","leftOnly":"7","both":"5","rightOnly":"9","outside":"4","universalLabel":"ξ = students"}}}}]},"e":"Football only has 7 and both sports have 5, so n(F) = 7 + 5 = 12. In total: 7 + 5 + 9 + 4 = 25 students.\n\nHint for next time: The whole F circle counts — both of its regions.","m":2,"df":"easy","tp":"sets and Venn diagrams","st":"reading a Venn diagram","cfg":{"source":"assess-prep-myp2-formative","question_number":15,"myp_criterion":"A","next_time_hint":"The whole F circle counts — both of its regions.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many students play football (including those who play both)?","kind":"numeric","points":1,"hints":["The whole F circle counts — both of its regions.","Add the ''football only'' region to the overlap region."],"answer":12,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many students are shown in the universal set?","kind":"numeric","points":1,"hints":["The universal set is everything inside the rectangle.","Add all four regions, including the outside region."],"answer":25,"tolerance":0}]}},{"n":16,"t":"assess_parts","p":"The universal set is ξ = {1, 2, 3, …, 12}. Set E contains the even numbers.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The universal set is ξ = {1, 2, 3, …, 12}. Set E contains the even numbers."}]}]},"e":"The even numbers up to 12 are 2, 4, 6, 8, 10, 12 — six numbers. The complement E′ has the other 6 numbers, so n(E′) = 6.\n\nHint for next time: Even means exactly divisible by 2.","m":2,"df":"easy","tp":"sets and Venn diagrams","st":"set notation and complement","cfg":{"source":"assess-prep-myp2-formative","question_number":16,"myp_criterion":"A","next_time_hint":"Even means exactly divisible by 2.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"List the elements of E, separated by commas.","kind":"text","points":1,"hints":["Even means exactly divisible by 2.","Work through 1 to 12 and keep the numbers divisible by 2."],"accepted":["2, 4, 6, 8, 10, 12","2,4,6,8,10,12","{2, 4, 6, 8, 10, 12}"]},{"id":"b","label":"(b)","prompt":"How many elements are in the complement of E, n(E′)?","kind":"numeric","points":1,"hints":["The complement is everything in ξ that is NOT in E.","Subtract n(E) from the total number of elements in ξ."],"answer":6,"tolerance":0}]}},{"n":17,"t":"assess_parts","p":"In a class of 30 students, 18 play chess, 12 play drums and 7 play both.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a class of 30 students, 18 play chess, 12 play drums and 7 play both."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Chess and drums in a class of 30","venn":{"leftLabel":"Chess","rightLabel":"Drums","leftOnly":"?","both":"7","rightOnly":"?","outside":"?","universalLabel":"ξ = 30 students"}}}}]},"e":"Chess only = 18 − 7 = 11. Drums only = 12 − 7 = 5. Playing something = 11 + 7 + 5 = 23, so neither = 30 − 23 = 7 students.\n\nHint for next time: Start in the overlap: the 7 who play both are counted inside the 18.","m":3,"df":"medium","tp":"sets and Venn diagrams","st":"working with a Venn diagram","cfg":{"source":"assess-prep-myp2-formative","question_number":17,"myp_criterion":"D","next_time_hint":"Start in the overlap: the 7 who play both are counted inside the 18.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many students play chess only?","kind":"numeric","points":1,"hints":["Start in the overlap: the 7 who play both are counted inside the 18.","Subtract the ''both'' students from the chess total."],"answer":11,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many students play neither activity?","kind":"numeric","points":2,"hints":["Fill every region of the Venn diagram first, then use the class total.","Add the three inside regions and subtract from 30."],"answer":7,"tolerance":0}]}},{"n":18,"t":"assess_parts","p":"For the numbers 1 to 40, A = {multiples of 3} and B = {multiples of 5}.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For the numbers 1 to 40, A = {multiples of 3} and B = {multiples of 5}."}]}]},"e":"Multiples of 3: 13 numbers; multiples of 5: 8 numbers; multiples of both (15 and 30): 2. Only A = 13 − 2 = 11. In A or B: 11 + 2 + 6 = 19, so in neither: 40 − 19 = 21.\n\nHint for next time: Count the multiples of 3 first, then remove those that are also multiples of 5.","m":2,"df":"medium","tp":"sets and Venn diagrams","st":"Venn diagrams with number sets","cfg":{"source":"assess-prep-myp2-formative","question_number":18,"myp_criterion":"B","next_time_hint":"Count the multiples of 3 first, then remove those that are also multiples of 5.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many numbers are in A but not in B?","kind":"numeric","points":1,"hints":["Count the multiples of 3 first, then remove those that are also multiples of 5.","Numbers in both sets are the multiples of 15."],"answer":11,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many numbers from 1 to 40 are in neither set?","kind":"numeric","points":1,"hints":["Build the three inside regions of the Venn diagram.","Add only-A, both and only-B, then subtract from 40."],"answer":21,"tolerance":0}]}},{"n":19,"t":"assess_parts","p":"In a universal set of 32 students, n(A) = 17, n(B) = 14 and n(A ∩ B) = 6.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a universal set of 32 students, n(A) = 17, n(B) = 14 and n(A ∩ B) = 6."}]}]},"e":"Only A = 17 − 6 = 11. n(A ∪ B) = 17 + 14 − 6 = 25 (the overlap is added twice, so subtract it once). Neither = 32 − 25 = 7.\n\nHint for next time: The overlap belongs to A as well — remove it from A''s total.","m":3,"df":"hard","tp":"sets and Venn diagrams","st":"union and intersection","cfg":{"source":"assess-prep-myp2-formative","question_number":19,"myp_criterion":"A","next_time_hint":"The overlap belongs to A as well — remove it from A''s total.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many are in A only?","kind":"numeric","points":1,"hints":["The overlap belongs to A as well — remove it from A''s total.","Subtract n(A ∩ B) from n(A)."],"answer":11,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find n(A ∪ B).","kind":"numeric","points":1,"hints":["Add the two sets, but the overlap has been counted twice.","Use n(A) + n(B) − n(A ∩ B)."],"answer":25,"tolerance":0},{"id":"c","label":"(c)","prompt":"How many are in neither set?","kind":"numeric","points":1,"hints":["Use the universal set size and your union answer.","Subtract n(A ∪ B) from 32."],"answer":7,"tolerance":0}]}},{"n":20,"t":"short_answer","p":"A bag contains 4 red, 3 blue and 5 green counters. One counter is chosen at random. What is the probability it is red? Give your answer as a fraction in its simplest form.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bag contains 4 red, 3 blue and 5 green counters. One counter is chosen at random. What is the probability it is red? Give your answer as a fraction in its simplest form."}]}]},"e":"There are 4 + 3 + 5 = 12 counters. P(red) = 4/12 = 1/3.\n\nHint for next time: Probability = favourable outcomes ÷ total outcomes.","m":1,"df":"easy","tp":"probability","st":"simple probability","cfg":{"source":"assess-prep-myp2-formative","question_number":20,"myp_criterion":"A","next_time_hint":"Probability = favourable outcomes ÷ total outcomes.","assessment_style":"assess_prep_typed","hints":["Probability = favourable outcomes ÷ total outcomes.","Count all the counters first, then write red counters over the total and simplify."],"accepted":["1/3","4/12","0.33","0.333"]}},{"n":21,"t":"short_answer","p":"A spinner was spun 60 times in an experiment. It landed on red 18 times. What is the experimental probability of landing on red? Give your answer as a fraction in its simplest form.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A spinner was spun 60 times in an experiment. It landed on red 18 times. What is the experimental probability of landing on red? Give your answer as a fraction in its simplest form."}]}]},"e":"Experimental probability = 18 ÷ 60 = 18/60 = 3/10.\n\nHint for next time: Experimental probability comes from trials: successes ÷ trials.","m":1,"df":"medium","tp":"probability","st":"experimental probability","cfg":{"source":"assess-prep-myp2-formative","question_number":21,"myp_criterion":"D","next_time_hint":"Experimental probability comes from trials: successes ÷ trials.","assessment_style":"assess_prep_typed","hints":["Experimental probability uses the results of the trials, not equally likely outcomes.","Write ''times it landed on red'' over ''total spins'', then simplify."],"accepted":["3/10","18/60","0.3"]}},{"n":22,"t":"assess_parts","p":"A fair six-sided dice is rolled once.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A fair six-sided dice is rolled once."}]}]},"e":"Even numbers are 2, 4, 6: P(even) = 3/6 = 1/2. Multiples of 3 are 3 and 6: P = 2/6 = 1/3.\n\nHint for next time: List the even faces of the dice first.","m":2,"df":"medium","tp":"probability","st":"simple probability","cfg":{"source":"assess-prep-myp2-formative","question_number":22,"myp_criterion":"A","next_time_hint":"List the even faces of the dice first.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What is the probability of rolling an even number? Give a fraction in its simplest form.","kind":"text","points":1,"hints":["List the even faces of the dice first.","Write even faces over 6 and simplify."],"accepted":["1/2","3/6","0.5"]},{"id":"b","label":"(b)","prompt":"What is the probability of rolling a multiple of 3? Give a fraction in its simplest form.","kind":"text","points":1,"hints":["List the multiples of 3 among 1 to 6 first.","Write those faces over 6 and simplify."],"accepted":["1/3","2/6","0.33","0.333"]}]}},{"n":23,"t":"assess_parts","p":"A bag contains 3 red, 2 blue and 5 yellow counters (10 in total). A counter is chosen at random.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bag contains 3 red, 2 blue and 5 yellow counters (10 in total). A counter is chosen at random."}]}]},"e":"P(not blue) = (3 + 5)/10 = 8/10 = 4/5. In 50 trials you would expect about 4/5 × 50 = 40 counters that are not blue.\n\nHint for next time: ''Not blue'' means red or yellow — count those counters.","m":2,"df":"hard","tp":"probability","st":"probability and expectation","cfg":{"source":"assess-prep-myp2-formative","question_number":23,"myp_criterion":"D","next_time_hint":"''Not blue'' means red or yellow — count those counters.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What is the probability the counter is NOT blue? Give a fraction in its simplest form.","kind":"text","points":1,"hints":["''Not blue'' means red or yellow — count those counters.","Add the red and yellow counters over the total, then simplify."],"accepted":["4/5","8/10","0.8"]},{"id":"b","label":"(b)","prompt":"In 50 trials, how many times would you EXPECT the counter not to be blue?","kind":"numeric","points":1,"hints":["Expected number = probability × number of trials.","Multiply your probability from (a), as a decimal or fraction, by 50."],"answer":40,"tolerance":0}]}},{"n":24,"t":"assess_parts","p":"For a school fête, juice is mixed from syrup and water in the ratio 1 : 4. One batch makes 2.5 litres of juice.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For a school fête, juice is mixed from syrup and water in the ratio 1 : 4. One batch makes 2.5 litres of juice."}]}]},"e":"One batch has 5 parts, so one part = 2.5 ÷ 5 = 0.5 litres of syrup. For 15 litres: 15 ÷ 2.5 = 6 batches, needing 6 × 0.5 = 3 litres of syrup.\n\nHint for next time: Start by finding the total number of parts in the ratio.","m":3,"df":"hard","tp":"mixed challenge","st":"ratio in a real context","cfg":{"source":"assess-prep-myp2-formative","question_number":24,"myp_criterion":"D","next_time_hint":"Start by finding the total number of parts in the ratio.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many litres of syrup are in one batch?","kind":"numeric","points":1,"hints":["Start by finding the total number of parts in the ratio.","Share 2.5 litres into 5 equal parts; syrup takes 1 part."],"answer":0.5,"tolerance":0.01,"unit":"litres"},{"id":"b","label":"(b)","prompt":"How many litres of syrup are needed to make 15 litres of juice?","kind":"numeric","points":2,"hints":["Work out how many batches 15 litres makes first.","Divide 15 by the size of one batch, then multiply by the syrup per batch."],"answer":3,"tolerance":0,"unit":"litres"}]}},{"n":25,"t":"open_ended","p":"Sam says: \"Doubling 3 : 5 to 6 : 10 changes the ratio, because the numbers are bigger.\" In 1–2 sentences, explain whether Sam is right, and justify your answer using what the ratio 3 : 5 means. (Marked by your teacher against the rubric.)","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sam says: \"Doubling 3 : 5 to 6 : 10 changes the ratio, because the numbers are bigger.\" In 1–2 sentences, explain whether Sam is right, and justify your answer using what the ratio 3 : 5 means. (Marked by your teacher against the rubric.)"}]}]},"e":"Sam is wrong. A ratio compares the relative sizes of the parts: 6 : 10 has the same relative shares as 3 : 5 because both sides were multiplied by the same number (2), so each side still takes the same fraction of the total (3/8 and 5/8). Changing a ratio needs the sides multiplied by different numbers.\n\nHint for next time: Equivalent ratios come from multiplying both sides by the same number.","m":3,"df":"hard","tp":"mixed challenge","st":"explain why: equivalent ratios","cfg":{"source":"assess-prep-myp2-formative","question_number":25,"myp_criterion":"C","next_time_hint":"Equivalent ratios come from multiplying both sides by the same number.","assessment_style":"assess_prep_typed","hints":["Think about what a ratio compares: absolute size, or relative shares?","Compare the fraction of the total each side represents in 3 : 5 and in 6 : 10."],"marking_criteria":"3 marks. 1: states Sam is wrong (the ratio is unchanged/equivalent). 1: explains that both sides were multiplied by the same number, so the ratio is equivalent. 1: justifies with the meaning of the parts (same shares/fractions of the total, e.g. 3/8 and 5/8, or an equivalent example). No credit for a bare ''he is wrong'' without justification.","response_tools":["rich_text","math","table"],"response_requirement":"text","response_guidance":"Write 1–2 clear sentences. Give your conclusion first, then justify it."}}]'::jsonb) as x
on conflict (id) do nothing;

insert into question_options (id, question_id, label, is_correct, position)
select ('b2000000-0000-4000-8000' || lpad((300000 + (q.config->>'question_number')::int * 100 + (v.idx - 1))::text, 12, '0'))::uuid,
       q.id, v.variant, true, v.idx::int
  from questions q
  cross join lateral jsonb_array_elements_text(q.config->'accepted') with ordinality as v(variant, idx)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp2-formative'
on conflict (id) do nothing;

insert into quiz_questions (quiz_id, question_id, position, points)
select 'b2000000-0000-4000-8000-000000000001', q.id, (q.config->>'question_number')::int, q.points
  from questions q
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp2-formative'
on conflict (quiz_id, question_id) do nothing;

insert into exams (id, organization_id, quiz_id, class_id, title, description, instructions, duration_minutes, status, access_code, shared_link_enabled, settings, created_by)
values ('b2000000-0000-4000-8000-000000000002', '0a400000-0000-4000-8000-000000000001', 'b2000000-0000-4000-8000-000000000001', '0a400000-0000-4000-8000-000000000107', 'MYP 2 Mathematics — Formative Assessment: Rate, Ratio, Proportion, Sets and Probability', 'Grade 7 · MYP 2 · Mathematics · Formative (Assess Prep). Rate, ratio, proportion and proportional reasoning, sets and two-set Venn diagrams, simple and experimental probability. Type every answer — there are no options to choose from.',
  'Type every answer in the box provided — there are no options to choose from. Multi-part questions have a separate box and separate marks for each part. Press the Hint button whenever you are stuck: hints show you the way but never give the answer, and using a hint costs no marks. You have 45 minutes. Your feedback shows the correct answer, a worked solution and a hint for next time for every question.',
  45, 'open', 'MYP2-FORM-2026', true,
  '{"proctoring":false,"require_screen_share":false,"randomize_questions":false,"randomize_options":false,"pass_mark_percent":50,"results_published":true,"access_mode":"shared_link","identity_fields":[],"eligible_class_ids":["0a400000-0000-4000-8000-000000000107"],"attempt_policy":"single_resume","assessment_kind":"formative","grade_level":"7","curriculum":"MYP 2","subject":"Mathematics","total_marks":50,"source":"assess-prep-myp2-formative"}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
on conflict (id) do nothing;

insert into question_hints (id, organization_id, exam_id, question_id, level, body, status, source, created_by, approved_by)
select ('b2000000-0000-4000-8000' || lpad((500000 + (q.config->>'question_number')::int * 10 + h.level)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', 'b2000000-0000-4000-8000-000000000002', q.id, h.level, h.body, 'published', 'manual', '3c3ed712-f409-4aa1-a645-816418e22ec4', '3c3ed712-f409-4aa1-a645-816418e22ec4'
  from questions q
  cross join lateral (values
    (1, case when q.type = 'assess_parts'
             then 'Work through the parts in order: later parts often build on earlier ones. Every part also has its own Hint button beside its answer box.'
             else q.config->'hints'->>0 end),
    (2, case when q.type = 'assess_parts'
             then 'For part (a), start here: ' || (q.config->'parts'->0->'hints'->>0)
             else q.config->'hints'->>1 end)
  ) as h(level, body)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp2-formative'
on conflict (id) do nothing;

